head.script:
// 테스트 설명, 유효성 값 설정
//  - column 샘플 관례 : textAlign 은 Body Column 에만 설정 (설정 영역 con 옵션 미생성)
//  - 본 샘플(_3) : 편집 상태 입력창 정렬 축 (text / textImage / calendar / drilldown)
//    select Column 은 가이드 전제 밖 대조용 (결과를 판정에 쓰지 않음)
//  - 정렬값 축은 column_P_textAlign_1, CSS 클래스 / setColumnStyle() / setCellStyle() 우선순위는 column_P_textAlign_2 소유
scwin.tData = {
    "description" : "[column > P > textAlign]<br/>Column 에 표시되는 텍스트의 가로 정렬 방법을 설정합니다.",
    "validation" : [
        "inputType='text','textImage','calendar','drilldown' 인 Column 은 편집 상태의 입력창에도 Cell 과 같은 정렬이 적용됩니다."
    ]
}



// Body Column 정보 (Body Column 인덱스 순)
scwin.bodyInfo = [
    { "id" : "name",   "label" : "이름(text)" },
    { "id" : "city",   "label" : "지역(textImage)" },
    { "id" : "inDate", "label" : "입사일(calendar)" },
    { "id" : "org",    "label" : "조직(drilldown)" },
    { "id" : "dept",   "label" : "부서(select)" }
];

// 편집 기록 [rowIndex + "_" + colId] = { td : 편집 진입 시 Cell 정렬, input : 입력창 정렬 }
scwin.gVar = { "edit" : {} };



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_textAlign.setValue("right");
    con_targetColumn.setValue("name");

    // 편집 진입(더블클릭) 시 입력창 정렬 기록 (페이지 로딩 시 1회만 등록)
    document.addEventListener("dblclick", scwin.onEditEnter, true);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - textAlign(con 값) 은 con_targetColumn 에서 고른 Body Column 1개에만 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }
    scwin.gVar.edit = {};

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[절차] 설정 Body Column 의 Cell 더블클릭 (조직 Column 은 아이콘이 아닌 글자 위) -> 편집 진입 -> Escape\n[확인] 편집 입력창 정렬 확인 버튼 (부서(select) 는 대조용)"', '', 'label1');

    let cTextAlign = con_textAlign.getValue();
    let cTarget = con_targetColumn.getValue();

    let strNameSpace = $c.gcm.getNameSpace();

    // 바인딩 dataList (depth : drilldown 계층 깊이)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="city" name="city" dataType="text"></w2:column>';
    strDlt += '<w2:column id="inDate" name="inDate" dataType="date"></w2:column>';
    strDlt += '<w2:column id="org" name="org" dataType="text"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "홍길동", "city" : "서울", "inDate" : "20261001", "org" : "영업본부", "depth" : "1", "dept" : "01" },
        { "name" : "김영희", "city" : "부산", "inDate" : "20261005", "org" : "영업1팀", "depth" : "2", "dept" : "02" }
    ], false);

    // 검증 대상 Body Column 속성
    let attr = function (id) {
        return (cTarget === id && cTextAlign !== '') ? ' textAlign="' + cTextAlign + '"' : '';
    };

    let strItem = '<w2:choices>'
                + '<w2:item><w2:label>영업</w2:label><w2:value>01</w2:value></w2:item>'
                + '<w2:item><w2:label>개발</w2:label><w2:value>02</w2:value></w2:item>'
                + '</w2:choices>';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:800px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    for (let i = 0; i < scwin.bodyInfo.length; i++) {
        strTarget += '<w2:column width="160" style="" inputType="text" id="h_' + scwin.bodyInfo[i].id + '" value="' + scwin.bodyInfo[i].label + '"></w2:column>';
    }
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="160" style="" id="name" inputType="text"' + attr("name") + '></w2:column>';
    strTarget += '<w2:column width="160" style="" id="city" inputType="textImage"' + attr("city") + '></w2:column>';
    strTarget += '<w2:column width="160" style="" id="inDate" inputType="calendar" dataType="date" displayFormat="yyyy-MM-dd"' + attr("inDate") + '></w2:column>';
    strTarget += '<w2:column width="160" style="" id="org" inputType="drilldown" depthColumn="depth" showDepth="2"' + attr("org") + '></w2:column>';
    strTarget += '<w2:column width="160" style="" id="dept" inputType="select"' + attr("dept") + '>' + strItem + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 셀 더블클릭(편집 진입) 시 편집 중인 Cell 과 입력창의 정렬 기록
scwin.onEditEnter = function (e) {
    if (typeof target1 === 'undefined' || !target1 || !target1.render.contains(e.target)) {
        return;
    }
    setTimeout(function () {
        if (!target1.isEditing()) {
            return;
        }
        let row = target1.getFocusedRowIndex();
        let colId = target1.getFocusedColumnID();
        let colIndex = target1.getColumnIndex(colId);
        let td = document.querySelector("td[id*='" + target1.id + "_cell_" + row + "_" + colIndex + "']");
        let el = document.activeElement;
        let isInput = !!el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA");
        let kind = "입력창";
        // select 는 입력창 대신 SelectBox 라벨 영역 (대조용)
        if (!isInput) {
            let box = document.querySelector("[id^='G_" + target1.id + "_'][id$='_selectbox_" + colId + "']");
            el = box ? box.querySelector(".w2selectbox_label") : null;
            isInput = !!el;
            kind = "SelectBox 라벨";
        }
        scwin.gVar.edit[row + "_" + colId] = {
            "row" : row,
            "colId" : colId,
            "td" : td ? { "style" : td.style.textAlign || "(없음)", "computed" : getComputedStyle(td).textAlign } : null,
            "input" : isInput ? { "kind" : kind, "style" : el.style.textAlign || "(없음)", "computed" : getComputedStyle(el).textAlign } : null
        };
    }, 150);
}



// 편집 진입 기록 출력
//  - validation 1 : 편집 진입 시 Cell(td) 정렬과 입력창 정렬 대조
scwin.btn_checkEdit_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let cTextAlign = con_textAlign.getValue();
    let cTarget = con_targetColumn.getValue();
    let label = {};
    for (let i = 0; i < scwin.bodyInfo.length; i++) {
        label[scwin.bodyInfo[i].id] = scwin.bodyInfo[i].label;
    }
    bottom.setReturnValue("textAlign : " + (cTextAlign === '' ? "(미설정)" : cTextAlign) + " / 설정 Column : " + label[cTarget]);

    for (let key in scwin.gVar.edit) {
        let rec = scwin.gVar.edit[key];
        let tdText = rec.td ? "td style = " + rec.td.style + ", 계산 = " + rec.td.computed : "td 없음";
        let inText = rec.input ? rec.input.kind + " style = " + rec.input.style + ", 계산 = " + rec.input.computed : "입력창 없음";
        bottom.setReturnValue("Row " + rec.row + " " + label[rec.colId] + " 편집 : " + tdText + " / " + inText);
    }
}
